(ns rainbow.algorithms.reference.floyd-cycle
  "Executable Floyd's cycle detection, matching the proved meet decision.")

(defn meet? [slow-position fast-position]
  (and (<= slow-position fast-position) (<= fast-position slow-position)))

(defn has-cycle?
  "Detect a cycle in the functional sequence generated by f from start.
  `terminal` is a sentinel meaning the sequence ended (no cycle)."
  [f start terminal]
  (loop [slow (f start), fast (f (f start))]
    (cond
      (or (= slow terminal) (= fast terminal)) false
      (meet? slow fast) true
      :else (recur (f slow) (f (f fast))))))
